@pytest.mark.parametrize("gesture", GESTURES) @pytest.mark.parametrize("viewport", SIZES, ids=SIZE_IDS) @pytest.mark.parametrize("seed, button, rows, focus_after", LAST_ROW_CASES) def test_R7_a_repeat_press_on_the_last_remove_removes_that_row_and_adds_nothing( open_app, seed, button, rows, focus_after, viewport, gesture): # SEC-01: the second click landed on "Add person" (people) and saved a blank person. The last item's second click # lands on inert space, so for items the focus check is what shows the guard: the press must not move focus to the body. page = open_app(seed=seed, viewport=viewport, touch=gesture == "touch-double").page before = page.locator(rows).count() page.evaluate(RECORD_BODY_CLICKS_JS) gesture_at(page, gesture, centre_of(page.get_by_role("button", name=button, exact=True))) assert page.locator(rows).count() == before - 1 assert stored(page)["bill"] == bill_without_last(seed, rows) # no blank row, and the id counter did not move > assert support.active_label(page) == focus_after E AssertionError: assert 'rate-service' == 'Add item' E E - Add item E + rate-service
