@pytest.mark.parametrize("gesture", REPEAT_GESTURES) @pytest.mark.parametrize("width", [375, 390]) def test_R7_a_repeat_press_on_a_chip_under_a_pending_price_error_never_removes_the_item(open_app, width, gesture): scout = open_app(seed=EIGHT_PEOPLE, viewport=(width, 3000)).page # tall: the whole bill is in view, so the scout's points are the second page's boxes = scout.evaluate(CHIP_BOXES_JS) price = scout.get_by_role("textbox", name="Item 1 price in RM", exact=True) price.fill("abc") price.press("Tab") settle(scout) landings = scout.evaluate(OVER_ITS_OWN_REMOVE_JS, boxes) assert landings, "no chip point lies over its own Remove once the error shows: this test no longer probes anything" page = open_app(seed=EIGHT_PEOPLE, viewport=(width, 3000), touch=gesture == "touch-double").page before = [item["id"] for item in stored(page)["bill"]["items"]] page.get_by_role("textbox", name="Item 1 price in RM", exact=True).fill("abc") # focus stays: the press below blurs it gesture_at(page, gesture, landings[0]) > assert [item["id"] for item in stored(page)["bill"]["items"]] == before # no item went ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ E AssertionError: assert ['i4', 'i6', 'i7'] == ['i4', 'i5', 'i6', 'i7'] E E At index 1 diff: 'i6' != 'i5' E Right contains one more item: 'i7' E Use -v to get more diff
